// src/components/Metrices/AutomationMetricMain/TestCaseCountTab.js

// CHANGE: full implementation of the Test Case Count UI with Manual/Automation tabs
import React, { useMemo, useState } from "react";
import "../../../styles/roiTabs.css"; // keep using your existing ROI tab styles

// CHANGE: automation sub-buttons (mirrors your ProjectSavingsTab)
const AUTO_SUB_TABS = [
    "Conformiq-Robot",
    "Standalone Robot",
    "Standalone Selenium (With Python/Java/C# etc)",
    "Robot (With Selenium / Playwright Library)",
    "SOA API",
    "UFT Scriptless",
    "UFT Scripted",
    "Java Only",
    "Python Only",
    "Other Utilities",
];

// CHANGE: three subsections per automation sub-tab
const AUTO_SECTIONS = [
  "New Automation",
  "Existing TCs Updated",
  "Execution (SIT + UAT)",
];

const num = (v) => (Number.isFinite(+v) ? +v : 0);

export default function TestCaseCountTab() {
  // CHANGE: top-level manual/automation tabs
  const [activeTab, setActiveTab] = useState("Manual"); // "Manual" | "Automation"

  // =========================
  // MANUAL TAB STATE
  // =========================
  // CHANGE: two sections on Manual tab: Test Designed & Test Executed (each with Func/Regression; Total is derived)
  const [manualDesigned, setManualDesigned] = useState({ func: 0, regression: 0 });
  const [manualExecuted, setManualExecuted] = useState({ func: 0, regression: 0 });

  const designedTotal = useMemo(
    () => num(manualDesigned.func) + num(manualDesigned.regression),
    [manualDesigned]
  );
  const executedTotal = useMemo(
    () => num(manualExecuted.func) + num(manualExecuted.regression),
    [manualExecuted]
  );

  // =========================
  // AUTOMATION TAB STATE
  // =========================
  // CHANGE: active automation sub-tab (buttons)
  const [activeAuto, setActiveAuto] = useState(AUTO_SUB_TABS[0]);

  // CHANGE: for each automation sub-tab, keep three sub-sections (each has Func/Regression)
  const mkCounts = () => ({ func: 0, regression: 0 });
  const mkAutoBundle = () => Object.fromEntries(AUTO_SECTIONS.map((s) => [s, mkCounts()]));
  const [autoBySub, setAutoBySub] = useState(
    Object.fromEntries(AUTO_SUB_TABS.map((k) => [k, mkAutoBundle()]))
  );

  const updateAuto = (subKey, section, field, value) => {
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        [section]: { ...prev[subKey][section], [field]: num(value) },
      },
    }));
  };

  const sectionTotal = (subKey, section) =>
    num(autoBySub[subKey][section].func) + num(autoBySub[subKey][section].regression);

  // =========================
  // RENDERERS
  // =========================
  const label = (text, tone = "green") => (
    <label className={`tab-label tab-label-${tone}`} style={{ marginBottom: 4 }}>
      {text}
    </label>
  );

  const numberBox = (value, onChange, disabled = false) => (
    <input
      className={`tab-input${disabled ? " tab-input-orange" : ""}`}
      style={{ width: 120, padding: "4px 6px" }}
      type="number"
      value={value}
      onChange={(e) => !disabled && onChange(num(e.target.value))}
      disabled={disabled}
    />
  );

  const ManualSection = ({ title, state, setState }) => (
    <div
      style={{
        display: "flex",
        gap: 16,
        alignItems: "flex-end",
        flexWrap: "wrap",
        padding: 12,
        border: "1px solid #e5e7eb",
        borderRadius: 8,
        background: "#fff",
      }}
    >
      <div style={{ minWidth: 200 }}>{label(title, "yellow")}</div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Func")}
        {numberBox(state.func, (v) => setState({ ...state, func: v }))}
      </div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Regression")}
        {numberBox(state.regression, (v) => setState({ ...state, regression: v }))}
      </div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Total", "orange")}
        {numberBox(num(state.func) + num(state.regression), () => {}, true /* disabled */)}
      </div>
    </div>
  );

  const AutomationSectionRow = ({ subKey, sectionName }) => {
    const S = autoBySub[subKey][sectionName];
    return (
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr repeat(3, max-content)",
          gap: 16,
          alignItems: "end",
          padding: 10,
          borderBottom: "1px dashed #e5e7eb",
        }}
      >
        <div>{label(sectionName, "yellow")}</div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Func")}
          {numberBox(S.func, (v) => updateAuto(subKey, sectionName, "func", v))}
        </div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Regression")}
          {numberBox(S.regression, (v) => updateAuto(subKey, sectionName, "regression", v))}
        </div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Total", "orange")}
          {numberBox(sectionTotal(subKey, sectionName), () => {}, true)}
        </div>
      </div>
    );
  };

  // =========================
  // PAGE
  // =========================
  return (
    <div className="tab-wrap">
      {/* CHANGE: Primary tabs */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <button
          className="btn-red"
          style={{ opacity: activeTab === "Manual" ? 1 : 0.65 }}
          onClick={() => setActiveTab("Manual")}
        >
          Manual
        </button>
        <button
          className="btn-red"
          style={{ opacity: activeTab === "Automation" ? 1 : 0.65 }}
          onClick={() => setActiveTab("Automation")}
        >
          Automation
        </button>
      </div>

      {activeTab === "Manual" ? (
        <>
          {/* CHANGE: Manual tab content */}
          <div className="tab-section tab-section-yellow">Test Designed</div>
          <ManualSection
            title="Test Designed"
            state={manualDesigned}
            setState={setManualDesigned}
          />

          <div style={{ height: 10 }} />

          <div className="tab-section tab-section-yellow">Test Executed</div>
          <ManualSection
            title="Test Executed"
            state={manualExecuted}
            setState={setManualExecuted}
          />
        </>
      ) : (
        <>
          {/* CHANGE: Automation tab content */}
          <div className="tab-section tab-section-yellow">Automation</div>

          {/* sub-tab buttons (reuse style from Savings tab) */}
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "8px 0 12px" }}>
            {AUTO_SUB_TABS.map((k) => (
              <button
                key={k}
                className="btn-red"
                onClick={() => setActiveAuto(k)}
                style={{ opacity: activeAuto === k ? 1 : 0.65 }}
              >
                {k}
              </button>
            ))}
          </div>

          {/* three sub-sections for the active automation sub-tab */}
          <div
            style={{
              border: "1px solid #e5e7eb",
              borderRadius: 8,
              overflow: "hidden",
              background: "#fff",
            }}
          >
            {AUTO_SECTIONS.map((sec) => (
              <AutomationSectionRow key={sec} subKey={activeAuto} sectionName={sec} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}
